import type { Nullable } from '@univerjs/core';

import { ErrorType } from '../../../basics/error-type';
import type { ArrayValueObject } from '../../../engine/value-object/array-value-object';
import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
import { BooleanValueObject } from '../../../engine/value-object/primitive-object';
import { BaseFunction } from '../../base-function';

export class And extends BaseFunction {
    override calculate(...logicals: BaseValueObject[]) {
        if (logicals.length === 0) {
            return new ErrorValueObject(ErrorType.NA);
        }

        let noBoolean = true;
        let result = true;

        for (let i = 0; i < logicals.length; i++) {
            const logical = logicals[i];

            if (logical.isError()) {
                return logical;
            }

            if (logical.isArray()) {
                let errorObject: Nullable<ErrorValueObject> = null;

                (logical as ArrayValueObject).iterator((valueObject) => {
                    if (valueObject == null || valueObject.isNull()) {
                        return true; // continue
                    }

                    if (valueObject.isError()) {
                        errorObject = valueObject as ErrorValueObject;
                        return false; // break
                    }

                    // String values within an array reference are ignored.
                    if (valueObject.isString()) {
                        return true; // continue
                    }

                    noBoolean = false;

                    if (!this._getBooleanValue(valueObject)) {
                        result = false;
                    }
                });

                if (errorObject != null) {
                    return errorObject;
                }
            } else {
                if (logical.isNull()) {
                    continue;
                }

                if (logical.isString()) {
                    const booleanValue = this._getBooleanValueFromString(logical);

                    // A string that cannot be interpreted as a logical value is ignored.
                    if (booleanValue == null) {
                        continue;
                    }

                    noBoolean = false;

                    if (!booleanValue) {
                        result = false;
                    }

                    continue;
                }

                noBoolean = false;

                if (!this._getBooleanValue(logical)) {
                    result = false;
                }
            }
        }

        if (noBoolean) {
            return new ErrorValueObject(ErrorType.VALUE);
        }

        return new BooleanValueObject(result);
    }

    private _getBooleanValue(valueObject: BaseValueObject): boolean {
        const value = valueObject.getValue();

        if (typeof value === 'boolean') {
            return value;
        }

        if (typeof value === 'number') {
            return value !== 0;
        }

        return !!value;
    }

    private _getBooleanValueFromString(valueObject: BaseValueObject): Nullable<boolean> {
        const value = `${valueObject.getValue()}`.toLocaleUpperCase();

        if (value === 'TRUE') {
            return true;
        }

        if (value === 'FALSE') {
            return false;
        }

        return null;
    }
}
