import { ErrorType } from '../../basics/error-type';
import { ArrayValueObject } from '../value-object/array-value-object';
import { type BaseValueObject, ErrorValueObject } from '../value-object/base-value-object';

export function getRowCount(valueObject: BaseValueObject): number {
    return valueObject.isArray() ? (valueObject as ArrayValueObject).getRowCount() : 1;
}

export function getColumnCount(valueObject: BaseValueObject): number {
    return valueObject.isArray() ? (valueObject as ArrayValueObject).getColumnCount() : 1;
}

/**
 * Expand a scalar or array value object to the given dimensions.
 *
 * - Scalars (and 1x1 arrays) broadcast to every position.
 * - A single-row array broadcasts down the rows; a single-column array broadcasts across the columns.
 * - Positions that fall outside the source array are filled with `defaultValue` (defaults to `#N/A`).
 */
export function expandArrayValueObject(
    rowCount: number,
    columnCount: number,
    valueObject: BaseValueObject,
    defaultValue?: BaseValueObject
): ArrayValueObject {
    const valueRowCount = getRowCount(valueObject);
    const valueColumnCount = getColumnCount(valueObject);

    const result: BaseValueObject[][] = [];

    for (let r = 0; r < rowCount; r++) {
        const row: BaseValueObject[] = [];

        for (let c = 0; c < columnCount; c++) {
            row.push(_pickValue(valueObject, valueRowCount, valueColumnCount, r, c, defaultValue));
        }

        result.push(row);
    }

    return new ArrayValueObject({
        calculateValueList: result,
        rowCount,
        columnCount,
        unitId: '',
        sheetId: '',
        row: -1,
        column: -1,
    });
}

function _pickValue(
    valueObject: BaseValueObject,
    valueRowCount: number,
    valueColumnCount: number,
    row: number,
    column: number,
    defaultValue?: BaseValueObject
): BaseValueObject {
    if (!valueObject.isArray()) {
        return valueObject;
    }

    const array = valueObject as ArrayValueObject;

    let targetRow = row;
    let targetColumn = column;

    if (valueRowCount === 1) {
        targetRow = 0;
    }

    if (valueColumnCount === 1) {
        targetColumn = 0;
    }

    if (targetRow < valueRowCount && targetColumn < valueColumnCount) {
        return array.get(targetRow, targetColumn);
    }

    return defaultValue ?? new ErrorValueObject(ErrorType.NA);
}
