import { ErrorType } from '../../../basics/error-type';
import type { ArrayValueObject } from '../../../engine/value-object/array-value-object';
import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
import { BooleanValueObject } from '../../../engine/value-object/primitive-object';
import { expandArrayValueObject, getColumnCount, getRowCount } from '../../../engine/utils/value-object-expand';
import { BaseFunction } from '../../base-function';

export class If extends BaseFunction {
    override calculate(logicTest: BaseValueObject, valueIfTrue: BaseValueObject, valueIfFalse?: BaseValueObject) {
        if (logicTest == null || valueIfTrue == null) {
            return new ErrorValueObject(ErrorType.NA);
        }

        const _valueIfFalse = valueIfFalse ?? new BooleanValueObject(false);

        if (!logicTest.isArray() && !valueIfTrue.isArray() && !_valueIfFalse.isArray()) {
            return this._handleSingleObject(logicTest, valueIfTrue, _valueIfFalse);
        }

        const maxRowLength = Math.max(
            getRowCount(logicTest),
            getRowCount(valueIfTrue),
            getRowCount(_valueIfFalse)
        );

        const maxColumnLength = Math.max(
            getColumnCount(logicTest),
            getColumnCount(valueIfTrue),
            getColumnCount(_valueIfFalse)
        );

        const naError = new ErrorValueObject(ErrorType.NA);

        const logicTestArray = expandArrayValueObject(maxRowLength, maxColumnLength, logicTest, naError);
        const valueIfTrueArray = expandArrayValueObject(maxRowLength, maxColumnLength, valueIfTrue, naError);
        const valueIfFalseArray = expandArrayValueObject(maxRowLength, maxColumnLength, _valueIfFalse, naError);

        return logicTestArray.map((logicTestValue, rowIndex, columnIndex) =>
            this._handleSingleObject(
                logicTestValue,
                valueIfTrueArray.get(rowIndex, columnIndex),
                valueIfFalseArray.get(rowIndex, columnIndex)
            )
        );
    }

    private _handleSingleObject(
        logicTest: BaseValueObject,
        valueIfTrue: BaseValueObject,
        valueIfFalse: BaseValueObject
    ): BaseValueObject {
        if (logicTest.isError()) {
            return logicTest;
        }

        const booleanValue = this._getBooleanValue(logicTest);

        if (booleanValue instanceof ErrorValueObject) {
            return booleanValue;
        }

        return booleanValue ? valueIfTrue : valueIfFalse;
    }

    private _getBooleanValue(logicTest: BaseValueObject): boolean | ErrorValueObject {
        if (logicTest.isNull()) {
            return false;
        }

        const value = logicTest.getValue();

        if (typeof value === 'boolean') {
            return value;
        }

        if (typeof value === 'number') {
            return value !== 0;
        }

        const stringValue = `${value}`.toLocaleUpperCase();

        if (stringValue === 'TRUE') {
            return true;
        }

        if (stringValue === 'FALSE') {
            return false;
        }

        return new ErrorValueObject(ErrorType.VALUE);
    }
}
