import { ErrorType } from '../../../basics/error-type';
import { ArrayValueObject } from '../../../engine/value-object/array-value-object';
import { type BaseValueObject, ErrorValueObject } from '../../../engine/value-object/base-value-object';
import { expandArrayValueObject, getColumnCount, getRowCount } from '../../../engine/utils/value-object-expand';
import { BaseFunction } from '../../base-function';

export class Iferror extends BaseFunction {
    override calculate(value: BaseValueObject, valueIfError: BaseValueObject) {
        if (value == null || valueIfError == null) {
            return new ErrorValueObject(ErrorType.NA);
        }

        if (!value.isArray() && !valueIfError.isArray()) {
            return value.isError() ? valueIfError : value;
        }

        const maxRowLength = Math.max(getRowCount(value), getRowCount(valueIfError));
        const maxColumnLength = Math.max(getColumnCount(value), getColumnCount(valueIfError));

        const naError = new ErrorValueObject(ErrorType.NA);

        const valueArray = expandArrayValueObject(maxRowLength, maxColumnLength, value, naError);
        const valueIfErrorArray = expandArrayValueObject(maxRowLength, maxColumnLength, valueIfError, naError);

        const result: BaseValueObject[][] = [];

        for (let r = 0; r < maxRowLength; r++) {
            const row: BaseValueObject[] = [];

            for (let c = 0; c < maxColumnLength; c++) {
                const valueObject = valueArray.get(r, c);

                if (valueObject.isError()) {
                    row.push(valueIfErrorArray.get(r, c));
                } else {
                    row.push(valueObject);
                }
            }

            result.push(row);
        }

        return new ArrayValueObject({
            calculateValueList: result,
            rowCount: maxRowLength,
            columnCount: maxColumnLength,
            unitId: '',
            sheetId: '',
            row: -1,
            column: -1,
        });
    }
}
