import { expandArrayValueObject, getColumnCount, getRowCount } from '../../../engine/utils/value-object-expand';
import { BaseFunction } from '../../base-function';

export class Concatenate extends BaseFunction {
    override calculate(...texts: BaseValueObject[]) {
        if (texts.length === 0) {
            return new ErrorValueObject(ErrorType.NA);
        }

        let maxRowLength = 1;
        let maxColumnLength = 1;

        for (let i = 0; i < texts.length; i++) {
            maxRowLength = Math.max(maxRowLength, getRowCount(texts[i]));
            maxColumnLength = Math.max(maxColumnLength, getColumnCount(texts[i]));
        }

        if (maxRowLength === 1 && maxColumnLength === 1) {
            return this._concatenateSingle(texts.map((text) => (text.isArray() ? (text as ArrayValueObject).getFirstCell() : text)));
        }

        const naError = new ErrorValueObject(ErrorType.NA);

        const expandedTexts = texts.map((text) => expandArrayValueObject(maxRowLength, maxColumnLength, text, naError));

        const result: BaseValueObject[][] = [];

        for (let r = 0; r < maxRowLength; r++) {
            const row: BaseValueObject[] = [];

            for (let c = 0; c < maxColumnLength; c++) {
                const cells = expandedTexts.map((text) => text.get(r, c));
                row.push(this._concatenateSingle(cells));
            }

            result.push(row);
        }

        return new ArrayValueObject({
            calculateValueList: result,
            rowCount: maxRowLength,
            columnCount: maxColumnLength,
            unitId: '',
            sheetId: '',
            row: -1,
            column: -1,
        });
    }

    private _concatenateSingle(cells: BaseValueObject[]): BaseValueObject {
        let result = '';

        for (let i = 0; i < cells.length; i++) {
            const cell = cells[i];

            if (cell.isError()) {
                return cell;
            }

            result += this._getText(cell);
        }

        return new StringValueObject(result, true);
    }

    private _getText(valueObject: BaseValueObject): string {
        if (valueObject.isNull()) {
            return '';
        }

        const value = valueObject.getValue();

        if (typeof value === 'boolean') {
            return value ? 'TRUE' : 'FALSE';
        }

        return `${value}`;
    }
}
