describe('validate', () => {
    it('ISBLANK', () => {
        expect(isblank.calculate(new NullValueObject(0)).getValue()).toBe(true);
        expect(isblank.calculate(new NumberValueObject(0)).getValue()).toBe(false);
        expect(isblank.calculate(new StringValueObject('')).getValue()).toBe(false);
        expect(isblank.calculate(new BooleanValueObject(false)).getValue()).toBe(false);
        expect(isblank.calculate(new ErrorValueObject(ErrorType.DIV_BY_ZERO)).getValue()).toBe(false);
