        // array ignores strings
        expect(and.calculate(new ArrayValueObject(`{TRUE,"x",TRUE}`)).getValue()).toBe(true);
        expect(and.calculate(new ArrayValueObject(`{TRUE,"x",FALSE}`)).getValue()).toBe(false);
